fn enc_run_overrides(out: &mut ::std::vec::Vec<u8>, v: &RunOverrides, depth: i32) {
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "nas_store");
    out.extend_from_slice(b": ");
    esc(out, &v.nas_store);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "store");
    out.extend_from_slice(b": ");
    esc(out, &v.store);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "log_sink");
    out.extend_from_slice(b": ");
    esc(out, &v.log_sink);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "log_service");
    out.extend_from_slice(b": ");
    esc(out, &v.log_service);
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

