struct CompactEncodedCounter { start: usize, pos: usize, count: usize, quoted: bool, escaped: bool }
impl CompactEncodedCounter {
    fn new(start: usize) -> Self { Self { start, pos: start, count: 0, quoted: false, escaped: false } }
    fn check(&mut self, out: &[u8], limit: usize) {
        if out.len()-self.start > 1048576 { std::panic::panic_any(Refusal { word: "encoded_size", offset: 0 }); }
        while self.pos < out.len() {
            let b = out[self.pos]; self.pos += 1;
            if !self.quoted && matches!(b, b' ' | b'\t' | b'\r' | b'\n') { continue; }
            self.count += 1;
            if self.count > limit { std::panic::panic_any(Refusal { word: "encoded_size", offset: 0 }); }
            if self.quoted {
                if self.escaped { self.escaped = false; } else if b == b'\\' { self.escaped = true; } else if b == b'"' { self.quoted = false; }
            } else if b == b'"' { self.quoted = true; }
        }
    }
}

fn check_encoded_size(r: &Reader<'_>, limit: usize) -> ::std::result::Result<(), Refusal> {
    let mut depth = r.depth; let mut quoted = false; let mut escaped = false; let mut count: usize = 0;
    for i in r.pos..r.buf.len() {
        if i-r.pos >= 1048576 { return r.refuse("encoded_size"); }
        let c = r.buf[i];
        if !quoted && matches!(c, b' ' | b'\t' | b'\r' | b'\n') { continue; }
        count += 1;
        if count > limit { return r.refuse("encoded_size"); }
        if quoted {
            if escaped { escaped = false; } else if c == b'\\' { escaped = true; } else if c == b'"' { quoted = false; }
        } else if c == b'"' { quoted = true; }
        else if c == b'{' || c == b'[' { depth += 1; if depth > 64 { return r.refuse("depth_exceeded"); } }
        else if c == b'}' || c == b']' { depth -= 1; if depth <= r.depth { return Ok(()); } }
    }
    Ok(())
}

