fn service_check_value(v: &Value) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0, limit: DEPTH_LIMIT };
    let n = v.text.len();
    if n > 4096 { return r.refuse("bad_value"); }
    if v.text.chars().any(char::is_control) { return r.refuse("bad_value"); }
    let n = v.choice.len();
    if n != 0 && !(1..=64).contains(&n) { return r.refuse("bad_value"); }
    if !v.choice.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'.' || c == b'-') { return r.refuse("bad_value"); }
    let n = v.text_list.len();
    if n > 128 { return r.refuse("bad_value"); }
    for oa_element in v.text_list.iter() {
    let n = oa_element.len();
    if !(1..=128).contains(&n) { return r.refuse("bad_value"); }
    }
    for oa_element in v.text_list.iter() {
    if oa_element.chars().any(char::is_control) { return r.refuse("bad_value"); }
    }
    let n = v.text_map.len();
    if n > 8 { return r.refuse("bad_value"); }
    for oa_element in v.text_map.keys() {
    let n = oa_element.len();
    if !(1..=64).contains(&n) { return r.refuse("bad_value"); }
    }
    for oa_element in v.text_map.keys() {
    if !oa_element.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'.' || c == b'-') { return r.refuse("bad_value"); }
    }
    for oa_element in v.text_map.values() {
    let n = oa_element.len();
    if n > 512 { return r.refuse("bad_value"); }
    }
    for oa_element in v.text_map.values() {
    if oa_element.chars().any(char::is_control) { return r.refuse("bad_value"); }
    }
    Ok(())
}

fn service_check_change(v: &Change) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0, limit: DEPTH_LIMIT };
    let n = v.key.len();
    if !(1..=64).contains(&n) { return r.refuse("bad_value"); }
    if !v.key.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'.' || c == b'-') { return r.refuse("bad_value"); }
    if let Some(value) = &v.set {
        service_check_value(value)?;
    }
    Ok(())
}

