        let arguments = service_encode(&args, service_check_oa_config_editor_replace_user_arguments, enc_oa_config_editor_replace_user_arguments, decode_oa_config_editor_replace_user_arguments).map_err(CallError::Refusal)?;
        let request = OAServiceFrame { version: 1, service: "abstraction.config/editor@1".into(), method: "ReplaceUser".into(), arguments };
        let frame = service_encode(&request, service_check_oa_service_frame, enc_oa_service_frame, decode_oa_service_frame).map_err(CallError::Refusal)?;
